examples.code:
MonarchAiPromptInput(
    "Message the assistant",
    text: $prompt,
    attachments: files,
    onAttach: {
        // Present PhotosPicker and add the picked files.
    },
    onReceiveFiles: { providers in
        files += providers.map { MonarchAiAttachmentTrayFile(id: UUID().uuidString, name: $0.suggestedName ?? "Image") }
    },
    onRemoveAttachment: { id in files.removeAll { $0.id == id } },
    onSubmit: { _ in files = [] }
)

examples.setup:
@State private var prompt = ""

private let commands = [
    MonarchSlashMenuItem(id: "summarize", label: "summarize", description: "Summarize the conversation"),
    MonarchSlashMenuItem(id: "translate", label: "translate", description: "Translate the last answer"),
]

examples.code:
MonarchAiPromptInput(
    "Message the assistant",
    text: $prompt,
    triggerMenu: {
        MonarchAiSlashCommands(text: $prompt, commands: commands) { command in
            "/\(command.label) "
        }
    },
    toolbar: { EmptyView() },
    footer: { EmptyView() },
    onSubmit: { _ in }
)

MonarchAiPromptInput(
    "Message the assistant",
    text: .constant(""),
    disabledReason: "Connect a provider to start."
) { _ in }
.disabled(true)
